// Daily run: last 3 days. Webhook run: body {secret, fromDate, toDate, pages} for backfill (50 transcripts per page).
let b = {}; let viaHook = false;
try { viaHook = $('Backfill hook').all().length > 0; } catch (e) { viaHook = false; }
if (viaHook) { b = $('Backfill hook').first().json.body || {}; if (b.secret !== 'sv-mail-2026-09-17-Kq7') { throw new Error('bad secret'); } }
const now = new Date();
const fromDate = b.fromDate || new Date(now.getTime() - 3 * 864e5).toISOString();
const toDate = b.toDate || now.toISOString();
const pages = Math.min(Number(b.pages) || 1, 20);
const out = [];
for (let p = 0; p < pages; p++) { out.push({ json: { fromDate, toDate, skip: p * 50 } }); }
return out;

const rows = []; const seen = {}; const errors = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.errors) { errors.push(JSON.stringify(j.errors).slice(0, 300)); continue; }
  for (const t of ((j.data || {}).transcripts || [])) {
    if (!t || !t.id || seen[t.id]) { continue; } seen[t.id] = 1;
    const title = String(t.title || '');
    // titles follow the calendar pattern 'Startup <> Investor and Sidana Ventures'
    const clean = title.replace(/\s+(and|\|)\s+(Sidana Ventures( LLP)?|Rakesh Sidana|Aditya SV|Ragini Sabharwal|Naman Bhardwaj)\b.*$/i, '');
    const parts = clean.split(/\s*<\s*>\s*/);
    const lines = (t.sentences || []).map(s => (s.speaker_name || 'Speaker') + ': ' + (s.text || '')).join('\n');
    const sm = t.summary || {};
    const list = v => Array.isArray(v) ? v.join('; ') : String(v || '');
    rows.push({ json: {
      ff_id: t.id, title,
      meeting_date: t.date ? new Date(Number(t.date)).toISOString() : null,
      duration_min: t.duration ? Math.round(Number(t.duration)) : null,
      organizer: t.organizer_email || '',
      attendees: (t.meeting_attendees || []).map(a => (a.displayName ? a.displayName + ' ' : '') + '<' + (a.email || '') + '>').join(', ') || list(t.participants),
      startup_guess: parts.length > 1 ? parts[0].trim() : '',
      investor_guess: parts.length > 1 ? parts.slice(1).join(' <> ').trim() : '',
      overview: list(sm.overview).slice(0, 5000),
      action_items: list(sm.action_items).slice(0, 5000),
      keywords: list(sm.keywords).slice(0, 500),
      transcript: lines, transcript_chars: lines.length,
      ff_url: t.transcript_url || '', synced_at: new Date().toISOString() } });
  }
}
if (errors.length && !rows.length) { throw new Error('Fireflies API error: ' + errors[0]); }
if (!rows.length) { return [{ json: { none: true } }]; }
return rows;

